    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <section class="card" aria-labelledby="support-title">
        <p class="eyebrow">Support request</p>
        <h1 id="support-title">Contact our support team</h1>
        <p class="intro">
          Send us your contact details and our team will follow up with the right next step.
        </p>
        <p class="required-note" id="required-note">
          Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
        </p>

        <form id="support-form" novalidate aria-describedby="required-note">
          <div class="form-field">
            <label for="full-name">
              Full name <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="full-name"
              name="full-name"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
            >
            <p class="error-message" id="full-name-error"></p>
          </div>

          <div class="form-field">
            <label for="email">
              Email address <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="email"
              name="email"
              type="email"
              autocomplete="email"
              inputmode="email"
              required
              aria-describedby="email-error"
            >
            <p class="error-message" id="email-error"></p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number (optional)</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-help phone-error"
            >
            <p class="helper-text" id="phone-help">Use 10 digits, optionally separated by spaces, dashes, or parentheses.</p>
            <p class="error-message" id="phone-error"></p>
          </div>

          <button type="submit">Send support request</button>
          <p class="status-message" id="form-status" role="status"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#support-form");
      const statusMessage = document.querySelector("#form-status");

      const fields = {
        fullName: {
          input: document.querySelector("#full-name"),
          error: document.querySelector("#full-name-error"),
          validate(value) {
            return value.trim() ? "" : "Error: Enter your full name.";
          },
        },
        email: {
          input: document.querySelector("#email"),
          error: document.querySelector("#email-error"),
          validate(value) {
            const trimmed = value.trim();
            if (!trimmed) {
              return "Error: Enter your email address.";
