   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>

     <main id="main-content">
       <section class="card" aria-labelledby="support-title">
         <p class="eyebrow">Support request</p>
         <h1 id="support-title">Contact our support team</h1>
         <p class="intro">
           Send us your contact details and our team will follow up with the right next step.
         </p>
         <p class="required-note" id="required-note">
           Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
         </p>

         <form id="support-form" novalidate aria-describedby="required-note">
           <div class="form-field">
             <label for="full-name">
               Full name <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
