               name="full-name"
               type="text"
               autocomplete="name"
               required
               aria-describedby="full-name-error"
             >
             <p class="error-message" id="full-name-error"></p>
           </div>

           <div class="form-field">
             <label for="email">
               Email address <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
               id="email"
               name="email"
               type="email"
               autocomplete="email"
               inputmode="email"
               required
               aria-describedby="email-error"
             >
             <p class="error-message" id="email-error"></p>
           </div>

           <div class="form-field">
             <label for="phone">Phone number (optional)</label>
             <input
               id="phone"
               name="phone"
               type="tel"
               autocomplete="tel"
               inputmode="tel"
               aria-describedby="phone-help phone-error"
             >
             <p class="helper-text" id="phone-help">Use 10 digits, optionally separated by spaces, dashes, or parentheses.</p>
             <p class="error-message" id="phone-error"></p>
           </div>

           <button type="submit">Send support request</button>
           <p class="status-message" id="form-status" role="status"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#support-form");
       const statusMessage = document.querySelector("#form-status");

       const fields = {
         fullName: {
           input: document.querySelector("#full-name"),
           error: document.querySelector("#full-name-error"),
           validate(value) {
             return value.trim() ? "" : "Error: Enter your full name.";
           },
         },
         email: {
           input: document.querySelector("#email"),
           error: document.querySelector("#email-error"),
           validate(value) {
             const trimmed = value.trim();
             if (!trimmed) {
               return "Error: Enter your email address.";
             }

             return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)
               ? ""
               : "Error: Enter a valid email address, such as name@example.com.";
           },
         },
         phone: {
           input: document.querySelector("#phone"),
           error: document.querySelector("#phone-error"),
           validate(value) {
             const trimmed = value.trim();
             if (!trimmed) {
               return "";
             }

             const digits = trimmed.replace(/\D/g, "");
             const allowedCharacters = /^[\d\s()+.-]+$/.test(trimmed);

             return allowedCharacters && digits.length === 10
               ? ""
               : "Error: Enter a 10-digit phone number using digits, spaces, dashes, or parentheses.";
